import{_ as e,C as n,o as s,c as d,a2 as t,j as a,E as l,a as r}from"./chunks/framework.C21TwvGF.js";const I=JSON.parse('{"title":"24-dars (Mentor). 24-dars: Flowalgorithmda chiziqli algoritmlar yaratish","description":"","frontmatter":{"title":"24-dars (Mentor). 24-dars: Flowalgorithmda chiziqli algoritmlar yaratish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":8,"link":"/mentor/8-sinf-cs/hafta-08/"},"g":24,"title":"24-dars: Flowalgorithmda chiziqli algoritmlar yaratish","lead":"Flowalgorithmda chiziqli algoritmlar yaratish","slide":"/slaydlar/8-sinf-cs/hafta-08/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-08/dars-3-test.html","student_link":"/8-sinf-cs/hafta-08/dars-3","tabs":[{"g":22,"link":"/mentor/8-sinf-cs/hafta-08/dars-1","current":false},{"g":23,"link":"/mentor/8-sinf-cs/hafta-08/dars-2","current":false},{"g":24,"link":"/mentor/8-sinf-cs/hafta-08/dars-3","current":true}],"prev":{"g":23,"title":"23-dars: Flowalgorithmda o‘zgaruvchilar va ma’lumot turlari bilan ishlash","link":"/mentor/8-sinf-cs/hafta-08/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-08/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-08/dars-3.md"}'),h={name:"mentor/8-sinf-cs/hafta-08/dars-3.md"},c={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},b={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},k={class:"blk"},p={id:"tezkor-nazorat-savollari",tabindex:"-1"},y={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function v(_,i,z,x,T,$){const o=n("Icon");return s(),d("div",null,[i[15]||(i[15]=t("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 8-hafta (3-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Nazariy tushunchalar (20 daqiqa) + Kompyuterda laboratoriya va amaliy loyihalar (55 daqiqa) + Xulosa (5 daqiqa)</p><hr>",2)),a("div",c,[a("h2",m,[l(o,{name:"file-text"}),i[0]||(i[0]=r(" Dars rejasi ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),i[2]||(i[2]=t("<ol><li><strong>Tashkiliy qism va o&#39;tgan mavzuni takrorlash (10 daqiqa)</strong><ul><li>23-darsdagi <code>Declare</code>, <code>Integer</code>, <code>Real</code>, <code>String</code> turlarini takrorlash.</li><li>O&#39;zgaruvchi nomlash qoidalari bo&#39;yicha tezkor viktorina.</li></ul></li><li><strong>Yangi mavzu bayoni: Chiziqli algoritmlar tuzilmasi (20 daqiqa)</strong><ul><li>Chiziqli algoritm nima? (Barcha buyruqlar hech qanday shartsiz, to&#39;g&#39;ri chiziq bo&#39;ylab, bittadan ketma-ket bajariladigan algoritm).</li><li>Chiziqli algoritmning blok-sxemadagi ko&#39;rinishi: Yuqoridan pastga tomon yo&#39;nalgan bir maromdagi zanjir.</li><li>Flowgorithmda arifmetik amallar: <ul><li>Qo&#39;shish: <code>+</code></li><li>Ayirish: <code>-</code></li><li>Ko&#39;paytirish: <code>*</code></li><li>Bo&#39;lish: <code>/</code></li><li>Qoldiqli bo&#39;lish: <code>%</code></li><li>Qavslar orqali amallar tartibini boshqarish: <code>(a + b) * c</code>.</li></ul></li><li>Formula asosida hisoblash algoritmlarini loyihalash: geometriya (yuza, perimetr), fizika (tezlik, yo&#39;l, vaqt), iqtisod (foiz, o&#39;rtacha qiymat).</li></ul></li><li><strong>Amaliy laboratoriya mashg&#39;uloti: Loyihalar yaratish (45 daqiqa)</strong><ul><li>1-loyiha: To&#39;g&#39;ri to&#39;rtburchak yuzi va perimetrini hisoblash.</li><li>2-loyiha: Uchta fan balining o&#39;rtacha arifmetik qiymatini topish.</li><li>3-loyiha: Foiz hisoblagich (bank omonati yoki do&#39;kondagi chegirma).</li><li>4-loyiha: Dasturni F6 (Step) yordamida qadam-baqadam tekshirish va xatolarni (0 ga bo&#39;lish, noto&#39;g&#39;ri tur) tuzatish.</li></ul></li><li><strong>Darsni yakunlash va baholash (5 daqiqa)</strong><ul><li>Dars xulosasi va tezkor nazorat savollari.</li><li>8-hafta bo&#39;yicha uyga vazifani tushuntirish.</li></ul></li></ol><hr>",2))]),a("div",u,[a("h2",g,[l(o,{name:"file-text"}),i[3]||(i[3]=r(" Mentor konspekti ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),i[5]||(i[5]=t('<h3 id="_1-chiziqli-algoritm-linear-algorithm-nima" tabindex="-1">1. Chiziqli algoritm (Linear Algorithm) nima? <a class="header-anchor" href="#_1-chiziqli-algoritm-linear-algorithm-nima" aria-label="Permalink to &quot;1. Chiziqli algoritm (Linear Algorithm) nima?&quot;">​</a></h3><ul><li><strong>Ta&#39;rif:</strong> Chiziqli algoritm — bu hech qanday shart tekshirilmaydigan, tarmoqlanmaydigan va biror qadam qayta takrorlanmaydigan, ya&#39;ni barcha buyruqlar yuqoridan pastga qarab qat&#39;iy ketma-ketlikda bir maromda bajariladigan algoritm turidir.</li><li><strong>Tuzilishi:</strong> $$\\text{Start} \\longrightarrow \\text{Declare} \\longrightarrow \\text{Input} \\longrightarrow \\text{Process (Hisob)} \\longrightarrow \\text{Output} \\longrightarrow \\text{End}$$</li><li><strong>Xususiyati:</strong> Agar algoritmda 5 ta blok bo&#39;lsa, har bir blok albatta bir marta ishlaydi. Hech qaysi blok tashlab ketilmaydi.</li></ul><h3 id="_2-flowgorithmda-arifmetik-operatorlar-va-ustunlik-tartibi" tabindex="-1">2. Flowgorithmda arifmetik operatorlar va ustunlik tartibi <a class="header-anchor" href="#_2-flowgorithmda-arifmetik-operatorlar-va-ustunlik-tartibi" aria-label="Permalink to &quot;2. Flowgorithmda arifmetik operatorlar va ustunlik tartibi&quot;">​</a></h3><p>Matematikada bo&#39;lgani kabi, dasturlashda ham amallarning qat&#39;iy ustunlik tartibi (precedence) mavjud:</p><ol><li>Qavslar ichidagi ifodalar: <code>(...)</code></li><li>Ko&#39;paytirish (<code>*</code>), bo&#39;lish (<code>/</code>) va qoldiq olish (<code>%</code>)</li><li>Qo&#39;shish (<code>+</code>) va ayirish (<code>-</code>)</li></ol><blockquote><p><strong>Ehtiyot bo&#39;ling!</strong> Masalan, uchta sonning o&#39;rtacha qiymatini hisoblashda:<br><code>orta = a + b + c / 3</code> yozilsa — bu <strong>XATO!</strong> Chunki avval faqat <code>c</code> 3 ga bo&#39;linadi.<br> To&#39;g&#39;ri ifoda: <code>orta = (a + b + c) / 3</code>.</p></blockquote><h3 id="_3-nolga-bo-lish-xatoligi-division-by-zero" tabindex="-1">3. Nolga bo&#39;lish xatoligi (Division by Zero) <a class="header-anchor" href="#_3-nolga-bo-lish-xatoligi-division-by-zero" aria-label="Permalink to &quot;3. Nolga bo&#39;lish xatoligi (Division by Zero)&quot;">​</a></h3><p>Chiziqli algoritmlarda bo&#39;lish amali (<code>/</code>) ishlatilganda, mahraj nolga teng bo&#39;lmasligi kerak. Hozircha tarmoqlanuvchi shartlarni (Decision) o&#39;tmaganimiz sababli, foydalanuvchiga musbat yoki noldan farqli son kiritishni tavsiya qilamiz (masalan: <code>Output &quot;Iltimos, noldan farqli son kiriting&quot;</code>).</p><hr>',9))]),a("div",b,[a("h2",q,[l(o,{name:"file-text"}),i[6]||(i[6]=r(" Amaliy topshiriqlar va yechimlar ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),i[8]||(i[8]=t('<h3 id="_1-topshiriq-to-g-ri-to-rtburchak-hisoblagichi-·-oson" tabindex="-1">1-topshiriq: To&#39;g&#39;ri to&#39;rtburchak hisoblagichi · oson <a class="header-anchor" href="#_1-topshiriq-to-g-ri-to-rtburchak-hisoblagichi-·-oson" aria-label="Permalink to &quot;1-topshiriq: To&#39;g&#39;ri to&#39;rtburchak hisoblagichi · oson&quot;">​</a></h3><p>Foydalanuvchidan to&#39;g&#39;ri to&#39;rtburchakning bo&#39;yi $a$ va eni $b$ kiritiladi. Uning yuzi ($S = a \\times b$) va perimetri ($P = 2 \\times (a + b)$) hisoblanib, ekranga chiqarilsin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real a, b, S, P</code></li><li><code>Output &quot;Bo&#39;yini kiriting:&quot;</code></li><li><code>Input a</code></li><li><code>Output &quot;Enini kiriting:&quot;</code></li><li><code>Input b</code></li><li><code>Assign S = a * b</code></li><li><code>Assign P = 2 * (a + b)</code></li><li><code>Output &quot;Yuzi: &quot; &amp; S &amp; &quot;, Perimetri: &quot; &amp; P</code></li></ol><hr><h3 id="_2-topshiriq-harorat-konvertori-kelsiy-→-kelvin-·-oson" tabindex="-1">2-topshiriq: Harorat konvertori (Kelsiy → Kelvin) · oson <a class="header-anchor" href="#_2-topshiriq-harorat-konvertori-kelsiy-→-kelvin-·-oson" aria-label="Permalink to &quot;2-topshiriq: Harorat konvertori (Kelsiy → Kelvin) · oson&quot;">​</a></h3><p>Harorat Selsiyda kiritiladi ($C$). Dastur uni Kelvin shkalasiga ($K = C + 273.15$) o&#39;girib chiqarsin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real c, k</code></li><li><code>Output &quot;Haroratni Selsiyda kiriting:&quot;</code></li><li><code>Input c</code></li><li><code>Assign k = c + 273.15</code></li><li><code>Output &quot;Kelvin shkalasida: &quot; &amp; k</code></li></ol><hr><h3 id="_3-topshiriq-o-rtacha-arifmetik-ball-·-o-rta" tabindex="-1">3-topshiriq: O&#39;rtacha arifmetik ball · o&#39;rta <a class="header-anchor" href="#_3-topshiriq-o-rtacha-arifmetik-ball-·-o-rta" aria-label="Permalink to &quot;3-topshiriq: O&#39;rtacha arifmetik ball · o&#39;rta&quot;">​</a></h3><p>O&#39;quvchining 3 ta fandan olgan bahosi kiritiladi (matematika, ingliz tili, informatika). Ularning o&#39;rtacha arifmetik balini hisoblang.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real m, i, inf, orta</code></li><li><code>Output &quot;Matematika balini kiriting:&quot;</code></li><li><code>Input m</code></li><li><code>Output &quot;Ingliz tili balini kiriting:&quot;</code></li><li><code>Input i</code></li><li><code>Output &quot;Informatika balini kiriting:&quot;</code></li><li><code>Input inf</code></li><li><code>Assign orta = (m + i + inf) / 3</code></li><li><code>Output &quot;O&#39;rtacha ball: &quot; &amp; orta</code></li></ol><hr><h3 id="_4-topshiriq-mashinaning-o-rtacha-tezligi-·-o-rta" tabindex="-1">4-topshiriq: Mashinaning o&#39;rtacha tezligi · o&#39;rta <a class="header-anchor" href="#_4-topshiriq-mashinaning-o-rtacha-tezligi-·-o-rta" aria-label="Permalink to &quot;4-topshiriq: Mashinaning o&#39;rtacha tezligi · o&#39;rta&quot;">​</a></h3><p>Bosib o&#39;tilgan umumiy masofa ($S$ km) va sarflangan vaqt ($t$ soat) berilgan. Mashinaning o&#39;rtacha tezligini ($v = S / t$) hisoblovchi chiziqli blok-sxema tuzing.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real s, t, v</code></li><li><code>Output &quot;Masofani kiriting (km):&quot;</code></li><li><code>Input s</code></li><li><code>Output &quot;Vaqtni kiriting (soat):&quot;</code></li><li><code>Input t</code></li><li><code>Assign v = s / t</code></li><li><code>Output &quot;O&#39;rtacha tezlik: &quot; &amp; v &amp; &quot; km/soat&quot;</code></li></ol><hr><h3 id="_5-topshiriq-bank-omonati-bo-yicha-yillik-daromad-·-qiyin" tabindex="-1">5-topshiriq: Bank omonati bo&#39;yicha yillik daromad · qiyin <a class="header-anchor" href="#_5-topshiriq-bank-omonati-bo-yicha-yillik-daromad-·-qiyin" aria-label="Permalink to &quot;5-topshiriq: Bank omonati bo&#39;yicha yillik daromad · qiyin&quot;">​</a></h3><p>Foydalanuvchi bankka qo&#39;ygan dastlabki pul miqdorini ($P$ so&#39;m) va yillik foiz stavkasini ($r$ %, masalan 24) kiritadi. 1 yil o&#39;tgach olinadigan sof foydani va umumiy summani hisoblang.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real p, r, foyda, jami</code></li><li><code>Output &quot;Boshlang&#39;ich omonat summasini kiriting:&quot;</code></li><li><code>Input p</code></li><li><code>Output &quot;Yillik foiz stavkasini kiriting (%):&quot;</code></li><li><code>Input r</code></li><li><code>Assign foyda = p * (r / 100)</code></li><li><code>Assign jami = p + foyda</code></li><li><code>Output &quot;1 yillik sof foyda: &quot; &amp; foyda &amp; &quot; so&#39;m&quot;</code></li><li><code>Output &quot;Hisobdagi jami pul: &quot; &amp; jami &amp; &quot; so&#39;m&quot;</code></li></ol><hr>',25))]),a("div",k,[a("h2",p,[l(o,{name:"file-text"}),i[9]||(i[9]=r(" Tezkor nazorat savollari ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),i[11]||(i[11]=t("<ol><li>Chiziqli algoritm deb qanday algoritmga aytiladi?</li><li>Chiziqli algoritmda shart tekshirish yoki orqaga qaytish bo&#39;ladimi?</li><li>Arifmetik amallarda qavslar nima uchun kerak? Misol keltiring.</li><li>Agar <code>a = 10</code>, <code>b = 2</code> bo&#39;lsa, <code>natija = a + b * 3</code> nechaga teng bo&#39;ladi? Nega?</li><li>Dasturda bo&#39;lish amali (<code>/</code>) bajarilganda qanday ehtiyot chorasi ko&#39;rilishi lozim?</li></ol><hr>",2))]),a("div",y,[a("h2",f,[l(o,{name:"house"}),i[12]||(i[12]=r(" Uyga vazifa ",-1)),i[13]||(i[13]=a("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),i[14]||(i[14]=a("ol",null,[a("li",null,"Uyga vazifa faylidagi 24-dars topshirig'ini Flowgorithmda to'liq bajarish."),a("li",null,"Uchburchakning asosi $a$ va balandligi $h$ berilganda uning yuzini ($S = \\frac{1}{2} a \\cdot h$) hisoblovchi blok-sxema loyihasini saqlash."),a("li",null,"8-hafta umumiy test savollariga tayyorgarlik ko'rish.")],-1))])])}const P=e(h,[["render",v]]);export{I as __pageData,P as default};
